import React from "react";

class ServiceCard extends React.Component {
  render() {
    const {
      title,
      category,
      background,
      icon,
    } = this.props;

    return (
      <div className="svc-card">
        <div
          className="svc-img"
          style={{
            background: background,
          }}
        >
          {icon}
        </div>

        <div className="svc-name">
          {title}
        </div>

        <div className="svc-cat">
          {category} ‹
        </div>
      </div>
    );
  }
}

export default ServiceCard;
